mapper.select:
WITH AccountStats AS ( SELECT CUR_SEQ, COUNT(*) AS total_enrolled, COUNT(*) FILTER (WHERE STATUS = 'ENROLLED') AS active_accounts, COUNT(*) FILTER (WHERE STATUS = 'DROPOUT') AS dropout_count, COUNT(*) FILTER (WHERE STATUS = 'EARLYOUT') AS earlyout_count, COUNT(*) FILTER (WHERE STATUS = 'GRADUATED') AS graduated_count, -- 수료 학생까지 포함하여 '통계 대상 인원' 산출 COUNT(*) FILTER (WHERE STATUS IN ('ENROLLED', 'GRADUATED')) AS active_and_graduated FROM lms.TB_ACCOUNT WHERE DEL_YN = 'N' -- 1. 전체 학적 통계에서 삭제된 계정 제외 GROUP BY CUR_SEQ ), TestStats AS ( /* 현재 삭제되지 않고 재학 중인 학생의 시험 제출 수만 집계 */ SELECT t.SUB_SEQ, COUNT(r.RESULT_SEQ) AS submitted_count FROM lms.TB_TEST t LEFT JOIN lms.TB_TEST_RESULT r ON t.TEST_SEQ = r.TEST_SEQ LEFT JOIN lms.TB_ACCOUNT acc ON r.account_seq = acc.account_seq WHERE acc.DEL_YN = 'N' -- 2. 삭제된 학생의 제출 기록은 통계에서 제외 -- 수료 상태인 학생의 제출 기록도 통계에 포함되도록 조건 수정 AND (acc.STATUS IN ('ENROLLED', 'GRADUATED') OR r.RESULT_SEQ IS NULL) GROUP BY t.SUB_SEQ ) SELECT c.CUR_SEQ AS cur_seq, c.CUR_NAME AS cur_name, c.ROOM AS class_name, c.TERM AS term, c.START_DATE || ' ~ ' || c.END_DATE AS period, c.ACCOUNT_SEQ AS account_seq, t.ACCOUNT_NAME AS teacher_name, COALESCE(ast.total_enrolled, 0) AS total_enrolled, COALESCE(ast.active_accounts, 0) AS active_accounts, COALESCE(ast.dropout_count, 0) AS dropout_count, COALESCE(ast.earlyout_count, 0) AS earlyout_count, COALESCE(ast.graduated_count, 0) AS graduated_count, COALESCE(ast.active_and_graduated, 0) AS active_and_graduated, -- 분모를 active_and_graduated로 변경하여 수료생 포함 비율 계산 ROUND(AVG( CASE WHEN COALESCE(ast.active_and_graduated, 0) = 0 THEN 0 ELSE (COALESCE(tst.submitted_count, 0)::NUMERIC / NULLIF(ast.active_and_graduated, 0) * 100) END ), 1) AS total_avg_ratio,
COALESCE( JSONB_AGG( JSONB_BUILD_OBJECT( 'subjectName', s.SUB_NAME, 'submittedCount', COALESCE(tst.submitted_count, 0), 'ratio', CASE WHEN COALESCE(ast.active_and_graduated, 0) = 0 THEN 0 ELSE ROUND(COALESCE(tst.submitted_count, 0)::NUMERIC / NULLIF(ast.active_and_graduated, 0) * 100, 1) END ) ORDER BY s.SUB_SEQ ) FILTER (WHERE s.SUB_SEQ IS NOT NULL), '[]'::JSONB ) AS subjects FROM lms.TB_CURRICULUM c LEFT JOIN lms.TB_ACCOUNT t ON c.ACCOUNT_SEQ = t.ACCOUNT_SEQ AND t.DEL_YN = 'N' -- 3. 담임 교수 정보 조회 시에도 삭제 여부 확인 LEFT JOIN AccountStats ast ON c.CUR_SEQ = ast.CUR_SEQ LEFT JOIN lms.TB_SUBJECT s ON c.CUR_SEQ = s.CUR_SEQ LEFT JOIN TestStats tst ON s.SUB_SEQ = tst.SUB_SEQ
AND c.STATUS = 'A'
AND c.ACCOUNT_SEQ = #{accountSeq}
AND TO_CHAR(c.START_DATE, 'YYYY') = #{year}
GROUP BY c.CUR_SEQ, c.CUR_NAME, c.ROOM, c.TERM, c.START_DATE, c.END_DATE, c.ACCOUNT_SEQ, t.ACCOUNT_NAME, ast.total_enrolled, ast.active_accounts, ast.dropout_count, ast.earlyout_count, ast.graduated_count, ast.active_and_graduated ORDER BY c.START_DATE DESC
